hl::game_api::ChangeLevelTransitionSummary::
    ChangeLevelPlayerTransferRuntimeIntegrationBlockerSnapshotSummary
BuildChangeLevelPlayerTransferRuntimeIntegrationBlockerSnapshot(
    const hl::game_api::ChangeLevelTransitionSummary::
        ChangeLevelPlayerTransferCheckpointSignalHookInstallResultConsumerBindingOutcomeActivationOutcomeSummary&
            activation_outcome)
{
    hl::game_api::ChangeLevelTransitionSummary::
        ChangeLevelPlayerTransferRuntimeIntegrationBlockerSnapshotSummary
            blocker_snapshot;
    blocker_snapshot.attempted = true;

    if (activation_outcome.prepared
        && activation_outcome
               .install_result_binding_outcome_activation_outcome_ready)
    {
        blocker_snapshot.prepared = true;
        blocker_snapshot.skipped = false;
        blocker_snapshot.decision_source =
            "player-transfer-checkpoint-signal-hook-install-result-consumer-binding-outcome-activation-outcome";
        blocker_snapshot.apply_target = activation_outcome.apply_target;
        blocker_snapshot.current_map = activation_outcome.current_map;
        blocker_snapshot.requested_map = activation_outcome.requested_map;
        blocker_snapshot.future_apply_phase =
            activation_outcome.future_apply_phase;
        blocker_snapshot.target_runtime_checkpoint =
            activation_outcome.target_runtime_checkpoint;
        blocker_snapshot.runtime_integration_candidate =
            activation_outcome.result_binding_outcome_activation_attempted
            && activation_outcome
                   .result_binding_outcome_activation_succeeded;
        blocker_snapshot.runtime_integration_blocked =
            !blocker_snapshot.runtime_integration_candidate;
        blocker_snapshot.runtime_integration_deferred =
            activation_outcome.result_binding_outcome_activation_deferred
            || activation_outcome.deferred;
        blocker_snapshot.blocking_stage =
            "result-consumer-binding-outcome-activation-outcome";
        blocker_snapshot.blocking_reason =
            activation_outcome
                    .result_binding_outcome_activation_outcome_reason.empty()
                ? std::string("binding-outcome-activation-outcome-reason-unavailable")
                : activation_outcome
                      .result_binding_outcome_activation_outcome_reason;
        blocker_snapshot.next_required_integration =
            "produce-binding-outcome-activation";
        blocker_snapshot.chain_terminal = true;
        blocker_snapshot.runtime_observation_suppressed =
            activation_outcome.runtime_observation_suppressed;
        blocker_snapshot.runtime_write_suppressed =
            activation_outcome.runtime_write_suppressed;
        blocker_snapshot.integration_blocker_snapshot_ready = true;
        blocker_snapshot.action =
            "no-op runtime integration blocker snapshot prepared";
        return blocker_snapshot;
    }

    blocker_snapshot.prepared = false;
    blocker_snapshot.integration_blocker_snapshot_ready = false;
    blocker_snapshot.short_circuit_reason =
        activation_outcome.short_circuit_reason;

    if (activation_outcome.skipped)
    {
        blocker_snapshot.skipped = true;
        blocker_snapshot.action = "runtime integration blocker snapshot skipped";
        return blocker_snapshot;
    }

    blocker_snapshot.skipped = false;
    blocker_snapshot.decision_source =
        "player-transfer-checkpoint-signal-hook-install-result-consumer-binding-outcome-activation-outcome";
    blocker_snapshot.apply_target = activation_outcome.apply_target;
    blocker_snapshot.current_map = activation_outcome.current_map;
    blocker_snapshot.requested_map = activation_outcome.requested_map;
    blocker_snapshot.future_apply_phase = activation_outcome.future_apply_phase;
    blocker_snapshot.target_runtime_checkpoint =
        activation_outcome.target_runtime_checkpoint;
    blocker_snapshot.runtime_integration_candidate = false;
    blocker_snapshot.runtime_integration_blocked = true;
    blocker_snapshot.runtime_integration_deferred =
        activation_outcome.result_binding_outcome_activation_deferred
        || activation_outcome.deferred;
    blocker_snapshot.blocking_stage =
        "result-consumer-binding-outcome-activation-outcome";
    blocker_snapshot.blocking_reason =
        activation_outcome
                .result_binding_outcome_activation_outcome_reason.empty()
            ? (activation_outcome.short_circuit_reason.empty()
                   ? std::string(
                         "binding-outcome-activation-outcome-unavailable")
                   : activation_outcome.short_circuit_reason)
            : activation_outcome
                  .result_binding_outcome_activation_outcome_reason;
    blocker_snapshot.next_required_integration =
        "produce-binding-outcome-activation";
    blocker_snapshot.chain_terminal = true;
    blocker_snapshot.runtime_observation_suppressed =
        activation_outcome.runtime_observation_suppressed;
    blocker_snapshot.runtime_write_suppressed =
        activation_outcome.runtime_write_suppressed;
    blocker_snapshot.action = "runtime integration blocker snapshot unavailable";
    return blocker_snapshot;
}

hl::game_api::ChangeLevelTransitionSummary::
    ChangeLevelPlayerTransferRuntimeCheckpointObservationSummary
BuildChangeLevelPlayerTransferRuntimeCheckpointObservation(
    const hl::game_api::ChangeLevelTransitionSummary::
        ChangeLevelPlayerTransferRuntimeIntegrationBlockerSnapshotSummary& blocker_snapshot,
    bool current_runtime_serveractivate_complete)
{
    hl::game_api::ChangeLevelTransitionSummary::
        ChangeLevelPlayerTransferRuntimeCheckpointObservationSummary
            checkpoint_observation;
    checkpoint_observation.attempted = true;

    if (blocker_snapshot.prepared
        && blocker_snapshot.integration_blocker_snapshot_ready
        && current_runtime_serveractivate_complete)
    {
        checkpoint_observation.prepared = true;
        checkpoint_observation.skipped = false;
        checkpoint_observation.decision_source =
            "runtime-integration-blocker-snapshot";
        checkpoint_observation.apply_target = blocker_snapshot.apply_target;
        checkpoint_observation.current_map = blocker_snapshot.current_map;
        checkpoint_observation.requested_map = blocker_snapshot.requested_map;
        checkpoint_observation.required_runtime_checkpoint =
            blocker_snapshot.target_runtime_checkpoint;
        checkpoint_observation.runtime_signal_source =
            "current-runtime-serveractivate-complete";
        checkpoint_observation.runtime_checkpoint_observed = true;
        checkpoint_observation.runtime_signal_backed = true;
        checkpoint_observation.observation_scope = "current-runtime-only";
        checkpoint_observation.target_runtime_observed = false;
        checkpoint_observation.runtime_integration_candidate = true;
        checkpoint_observation.runtime_integration_blocked = true;
        checkpoint_observation.blocking_reason =
            "target-map-runtime-not-yet-available";
        checkpoint_observation.next_required_integration =
            "target-map-serveractivate-observation";
        checkpoint_observation.runtime_observation_read_only = true;
        checkpoint_observation.runtime_write_suppressed =
            blocker_snapshot.runtime_write_suppressed;
        checkpoint_observation.runtime_checkpoint_observation_ready = true;
        checkpoint_observation.action =
            "runtime checkpoint observation latched";
        return checkpoint_observation;
    }

    checkpoint_observation.prepared = false;
    checkpoint_observation.runtime_checkpoint_observation_ready = false;
    checkpoint_observation.short_circuit_reason =
        blocker_snapshot.short_circuit_reason;

    if (blocker_snapshot.skipped)
    {
        checkpoint_observation.skipped = true;
        checkpoint_observation.action =
            "runtime checkpoint observation skipped";
        return checkpoint_observation;
    }

    checkpoint_observation.skipped = false;
    checkpoint_observation.decision_source =
        blocker_snapshot.attempted ? "runtime-integration-blocker-snapshot"
                                   : std::string();
    checkpoint_observation.apply_target = blocker_snapshot.apply_target;
    checkpoint_observation.current_map = blocker_snapshot.current_map;
    checkpoint_observation.requested_map = blocker_snapshot.requested_map;
    checkpoint_observation.required_runtime_checkpoint =
        blocker_snapshot.target_runtime_checkpoint;
    checkpoint_observation.runtime_signal_source =
        "current-runtime-serveractivate-complete";
    checkpoint_observation.runtime_checkpoint_observed =
        current_runtime_serveractivate_complete;
    checkpoint_observation.runtime_signal_backed =
        current_runtime_serveractivate_complete;
    checkpoint_observation.observation_scope = "current-runtime-only";
    checkpoint_observation.target_runtime_observed = false;
    checkpoint_observation.runtime_integration_candidate = false;
    checkpoint_observation.runtime_integration_blocked =
        blocker_snapshot.runtime_integration_blocked
        || !current_runtime_serveractivate_complete;
    checkpoint_observation.blocking_reason =
        current_runtime_serveractivate_complete
        ? (blocker_snapshot.blocking_reason.empty()
               ? std::string("runtime-integration-blocker-snapshot-unavailable")
               : blocker_snapshot.blocking_reason)
        : std::string("current-runtime-serveractivate-incomplete");
    checkpoint_observation.next_required_integration =
        current_runtime_serveractivate_complete
        ? blocker_snapshot.next_required_integration
        : std::string("current-runtime-serveractivate-observation");
    checkpoint_observation.runtime_observation_read_only = true;
    checkpoint_observation.runtime_write_suppressed =
        blocker_snapshot.runtime_write_suppressed;
    checkpoint_observation.action =
        current_runtime_serveractivate_complete
        ? "runtime checkpoint observation unavailable"
        : "runtime checkpoint observation waiting on current runtime serveractivate";
    return checkpoint_observation;
}

hl::game_api::ChangeLevelTransitionSummary::
    ChangeLevelPlayerTransferTargetRuntimeCheckpointObservationSummary
    BuildChangeLevelPlayerTransferTargetRuntimeCheckpointObservation(
        const hl::game_api::ChangeLevelTransitionSummary::
            ChangeLevelPlayerTransferRuntimeCheckpointObservationSummary&
                checkpoint_observation,
        std::string_view active_runtime_map)
{
    hl::game_api::ChangeLevelTransitionSummary::
        ChangeLevelPlayerTransferTargetRuntimeCheckpointObservationSummary
            target_runtime_observation;
    target_runtime_observation.attempted = true;

    const std::string active_runtime_map_text(active_runtime_map);
    const bool active_runtime_map_available = !active_runtime_map_text.empty();
    const bool active_runtime_matches_current =
        active_runtime_map_available
        && active_runtime_map_text == checkpoint_observation.current_map;
    const bool target_runtime_available =
        active_runtime_map_available
        && active_runtime_map_text == checkpoint_observation.requested_map;

    if (checkpoint_observation.prepared
        && checkpoint_observation.runtime_checkpoint_observation_ready
        && active_runtime_matches_current)
    {
        target_runtime_observation.prepared = true;
        target_runtime_observation.skipped = false;
        target_runtime_observation.decision_source =
            "runtime-checkpoint-observation";
        target_runtime_observation.apply_target =
            checkpoint_observation.apply_target;
        target_runtime_observation.current_map =
            checkpoint_observation.current_map;
        target_runtime_observation.requested_map =
            checkpoint_observation.requested_map;
        target_runtime_observation.required_runtime_checkpoint =
            checkpoint_observation.required_runtime_checkpoint;
        target_runtime_observation.runtime_signal_source =
            checkpoint_observation.runtime_signal_source;
        target_runtime_observation.active_runtime_map = active_runtime_map_text;
        target_runtime_observation.target_runtime_map =
            checkpoint_observation.requested_map;
        target_runtime_observation.runtime_signal_backed =
            checkpoint_observation.runtime_signal_backed;
        target_runtime_observation.observation_scope = "target-runtime";
        target_runtime_observation.current_runtime_checkpoint_observed =
            checkpoint_observation.runtime_checkpoint_observed;
        target_runtime_observation.target_runtime_available =
            target_runtime_available;
        target_runtime_observation.target_runtime_checkpoint_observed =
            target_runtime_available
            && checkpoint_observation.runtime_checkpoint_observed;
        target_runtime_observation.target_runtime_checkpoint_observable =
            target_runtime_available
            && checkpoint_observation.runtime_checkpoint_observed;
        target_runtime_observation.target_runtime_observation_blocked =
            !target_runtime_observation.target_runtime_checkpoint_observable;
        target_runtime_observation.target_runtime_observation_reason =
            target_runtime_available ? std::string()
                                     : std::string("target-map-not-active");
        target_runtime_observation.next_required_integration =
            target_runtime_available
            ? std::string("observe-target-runtime-checkpoint")
            : std::string("materialize-target-map-runtime");
        target_runtime_observation.runtime_observation_read_only =
            checkpoint_observation.runtime_observation_read_only;
        target_runtime_observation.runtime_write_suppressed =
            checkpoint_observation.runtime_write_suppressed;
        target_runtime_observation.target_runtime_checkpoint_observation_ready =
            true;
        target_runtime_observation.action =
            target_runtime_available
            ? "target runtime checkpoint observable"
            : "target runtime checkpoint not yet observable";
        return target_runtime_observation;
    }

    target_runtime_observation.prepared = false;
    target_runtime_observation.target_runtime_checkpoint_observation_ready = false;
    target_runtime_observation.short_circuit_reason =
        checkpoint_observation.short_circuit_reason;

    if (checkpoint_observation.skipped)
    {
        target_runtime_observation.skipped = true;
        target_runtime_observation.action =
            "target runtime checkpoint observation skipped";
        return target_runtime_observation;
    }

    target_runtime_observation.skipped = false;
    target_runtime_observation.decision_source =
        checkpoint_observation.attempted ? "runtime-checkpoint-observation"
                                         : std::string();
    target_runtime_observation.apply_target = checkpoint_observation.apply_target;
    target_runtime_observation.current_map = checkpoint_observation.current_map;
    target_runtime_observation.requested_map =
        checkpoint_observation.requested_map;
    target_runtime_observation.required_runtime_checkpoint =
        checkpoint_observation.required_runtime_checkpoint;
    target_runtime_observation.runtime_signal_source =
        checkpoint_observation.runtime_signal_source;
    target_runtime_observation.active_runtime_map = active_runtime_map_text;
    target_runtime_observation.target_runtime_map =
        checkpoint_observation.requested_map;
    target_runtime_observation.runtime_signal_backed =
        checkpoint_observation.runtime_signal_backed;
    target_runtime_observation.observation_scope = "target-runtime";
    target_runtime_observation.current_runtime_checkpoint_observed =
        checkpoint_observation.runtime_checkpoint_observed;
    target_runtime_observation.target_runtime_available =
        target_runtime_available;
    target_runtime_observation.target_runtime_checkpoint_observed =
        target_runtime_available
        && checkpoint_observation.runtime_checkpoint_observed;
    target_runtime_observation.target_runtime_checkpoint_observable =
        target_runtime_available
        && checkpoint_observation.runtime_checkpoint_observed;
    target_runtime_observation.target_runtime_observation_blocked =
        !target_runtime_observation.target_runtime_checkpoint_observable;
    target_runtime_observation.runtime_observation_read_only =
        checkpoint_observation.runtime_observation_read_only;
    target_runtime_observation.runtime_write_suppressed =
        checkpoint_observation.runtime_write_suppressed;

    if (!checkpoint_observation.runtime_checkpoint_observation_ready)
    {
        target_runtime_observation.target_runtime_observation_reason =
            checkpoint_observation.runtime_checkpoint_observed
            ? std::string("current-runtime-checkpoint-observation-unavailable")
            : std::string("current-runtime-checkpoint-not-observed");
        target_runtime_observation.next_required_integration =
            checkpoint_observation.next_required_integration;
        target_runtime_observation.action =
            "target runtime checkpoint observation waiting on current runtime checkpoint";
        return target_runtime_observation;
    }

    if (!active_runtime_map_available)
    {
        target_runtime_observation.target_runtime_observation_reason =
            "active-runtime-map-unavailable";
        target_runtime_observation.next_required_integration =
            "capture-active-runtime-map-identity";
    }
    else if (!active_runtime_matches_current)
    {
        target_runtime_observation.target_runtime_observation_reason =
            "active-runtime-map-mismatch";
        target_runtime_observation.next_required_integration =
            "reconcile-active-runtime-map-identity";
    }
    else
    {
        target_runtime_observation.target_runtime_observation_reason =
            target_runtime_available ? std::string()
                                     : std::string("target-map-not-active");
        target_runtime_observation.next_required_integration =
            target_runtime_available
            ? std::string("observe-target-runtime-checkpoint")
            : std::string("materialize-target-map-runtime");
    }

    target_runtime_observation.action =
        "target runtime checkpoint observation unavailable";
    return target_runtime_observation;
}

hl::game_api::ChangeLevelTransitionSummary::
    ChangeLevelPlayerTransferTargetRuntimeMaterializationPlanSummary
    BuildChangeLevelPlayerTransferTargetRuntimeMaterializationPlan(
        const hl::game_api::ChangeLevelTransitionSummary::
            ChangeLevelPlayerTransferTargetRuntimeCheckpointObservationSummary&
                target_runtime_observation,
        const hl::game_api::ChangeLevelTransitionSummary::
            ChangeLevelBootstrapPlanSummary& plan)
{
    hl::game_api::ChangeLevelTransitionSummary::
        ChangeLevelPlayerTransferTargetRuntimeMaterializationPlanSummary
            materialization_plan;
    materialization_plan.attempted = true;

    if (target_runtime_observation.prepared
        && target_runtime_observation
               .target_runtime_checkpoint_observation_ready
        && plan.prepared && !target_runtime_observation.target_runtime_available
        && !target_runtime_observation.target_runtime_checkpoint_observed)
    {
        materialization_plan.prepared = true;
        materialization_plan.skipped = false;
        materialization_plan.decision_source =
            "target-runtime-checkpoint-observation";
        materialization_plan.apply_target =
            target_runtime_observation.apply_target;
        materialization_plan.current_map =
            target_runtime_observation.current_map;
        materialization_plan.requested_map =
            target_runtime_observation.requested_map;
        materialization_plan.active_runtime_map =
            target_runtime_observation.active_runtime_map;
        materialization_plan.target_runtime_map =
            target_runtime_observation.target_runtime_map;
        materialization_plan.target_bsp_path = plan.target_bsp_path;
        materialization_plan.landmark = plan.landmark;
        materialization_plan.target_worldspawn_present =
            plan.target_worldspawn_present;
        materialization_plan.target_entity_parse_ok =
            plan.target_entity_parse_ok;
        materialization_plan.materialization_candidate = true;
        materialization_plan.materialization_planned = true;
        materialization_plan.materialization_execution_suppressed = true;
        materialization_plan.materialization_mode = "no-op";
        materialization_plan.target_runtime_available =
            target_runtime_observation.target_runtime_available;
        materialization_plan.target_runtime_checkpoint_observed =
            target_runtime_observation.target_runtime_checkpoint_observed;
        materialization_plan.next_required_integration =
            "target-runtime-bootstrap-execution";
        materialization_plan.runtime_observation_read_only =
            target_runtime_observation.runtime_observation_read_only;
        materialization_plan.runtime_write_suppressed =
            target_runtime_observation.runtime_write_suppressed;
        materialization_plan.target_runtime_materialization_plan_ready = true;
        materialization_plan.action =
            "no-op target runtime materialization plan prepared";
        return materialization_plan;
    }

    materialization_plan.prepared = false;
    materialization_plan.target_runtime_materialization_plan_ready = false;
    materialization_plan.short_circuit_reason =
        !target_runtime_observation.short_circuit_reason.empty()
        ? target_runtime_observation.short_circuit_reason
        : plan.short_circuit_reason;

    if (target_runtime_observation.skipped || plan.skipped)
    {
        materialization_plan.skipped = true;
        materialization_plan.action =
            "target runtime materialization plan skipped";
        return materialization_plan;
    }

    materialization_plan.skipped = false;
    materialization_plan.decision_source =
        target_runtime_observation.attempted
        ? std::string("target-runtime-checkpoint-observation")
        : std::string();
    materialization_plan.apply_target = target_runtime_observation.apply_target;
    materialization_plan.current_map = target_runtime_observation.current_map;
    materialization_plan.requested_map =
        target_runtime_observation.requested_map;
    materialization_plan.active_runtime_map =
        target_runtime_observation.active_runtime_map;
    materialization_plan.target_runtime_map =
        target_runtime_observation.target_runtime_map;
    materialization_plan.target_bsp_path = plan.target_bsp_path;
    materialization_plan.landmark = plan.landmark;
    materialization_plan.target_worldspawn_present =
        plan.target_worldspawn_present;
    materialization_plan.target_entity_parse_ok = plan.target_entity_parse_ok;
    materialization_plan.target_runtime_available =
        target_runtime_observation.target_runtime_available;
    materialization_plan.target_runtime_checkpoint_observed =
        target_runtime_observation.target_runtime_checkpoint_observed;
    materialization_plan.runtime_observation_read_only =
        target_runtime_observation.runtime_observation_read_only;
    materialization_plan.runtime_write_suppressed =
        target_runtime_observation.runtime_write_suppressed;

    if (!target_runtime_observation.target_runtime_checkpoint_observation_ready)
    {
        materialization_plan.action =
            "target runtime materialization plan waiting on target runtime checkpoint observation";
        return materialization_plan;
    }

    materialization_plan.action =
        "target runtime materialization plan not required";
    return materialization_plan;
}

