bool IsDedicatedSlotConnectedOccupant(const DedicatedPlayerRuntimeSlot& slot_state)
{
    return slot_state.occupied
        && slot_state.connected
        && slot_state.lifecycle_state != DedicatedPlayerLifecycleState::kDisconnected;
}

int CountDedicatedQueryPlayers(const DedicatedMultiplayerFoundationRuntime& runtime)
{
    int players = 0;
    for (const DedicatedPlayerRuntimeSlot& slot_state : runtime.slots)
    {
        if (IsDedicatedSlotConnectedOccupant(slot_state))
        {
            ++players;
        }
    }

    return players;
}

int FindFreeDedicatedAdmissionSlot(const EngineShimState& state)
{
    for (int slot = 1; slot <= state.server_state.maxclients; ++slot)
    {
        const DedicatedPlayerRuntimeSlot* slot_state = nullptr;
        for (const DedicatedPlayerRuntimeSlot& candidate : state.dedicated_multiplayer_foundation.slots)
        {
            if (candidate.slot == slot)
            {
                slot_state = &candidate;
                break;
            }
        }

        if (slot_state == nullptr || !IsDedicatedSlotConnectedOccupant(*slot_state))
        {
            return slot;
        }
    }

    return 0;
}

bool AdmitDedicatedLoopbackPreauthPlayer(
    EngineShimState& state,
    std::string_view session_id,
    std::string_view player_name,
    bool count_surface_accept,
    int* admitted_slot,
    std::string* reject_reason)
{
    if (admitted_slot != nullptr)
    {
        *admitted_slot = 0;
    }
    if (reject_reason != nullptr)
    {
        reject_reason->clear();
    }

    if (CountDedicatedQueryPlayers(state.dedicated_multiplayer_foundation)
        >= state.server_state.maxclients)
    {
        if (count_surface_accept)
        {
            ++state.dedicated_connect_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "server-full";
        }
        return false;
    }

    const int slot = FindFreeDedicatedAdmissionSlot(state);
    if (slot <= 0)
    {
        if (count_surface_accept)
        {
            ++state.dedicated_connect_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "no-authoritative-slot";
        }
        return false;
    }

    DedicatedPlayerRuntimeSlot& slot_state = EnsureDedicatedPlayerRuntimeSlot(
        state.dedicated_multiplayer_foundation,
        slot,
        session_id,
        player_name);
    if (count_surface_accept)
    {
        slot_state.external_loopback_admission = true;
    }
    PrimeDedicatedClientEdict(state, slot_state);
    RecordDedicatedLifecycleTransition(
        state.dedicated_multiplayer_foundation,
        slot_state,
        DedicatedPlayerLifecycleState::kReservedConnecting,
        "loopback connectionless preauth reserved authoritative client slot "
            + std::to_string(slot));
    RecordDedicatedLifecycleTransition(
        state.dedicated_multiplayer_foundation,
        slot_state,
        DedicatedPlayerLifecycleState::kConnected,
        "loopback connectionless preauth accepted; signon/gameplay transport intentionally pending");

    if (count_surface_accept)
    {
        ++state.dedicated_connect_surface.accepted;
        state.dedicated_last_external_session_id = std::string(session_id);
        state.dedicated_last_external_slot = slot;
    }
    if (admitted_slot != nullptr)
    {
        *admitted_slot = slot;
    }
    return true;
}

DedicatedPlayerRuntimeSlot* FindDedicatedPlayerRuntimeSlotBySession(
    DedicatedMultiplayerFoundationRuntime& runtime,
    std::string_view session_id)
{
    if (session_id.empty())
    {
        return nullptr;
    }

    for (DedicatedPlayerRuntimeSlot& slot_state : runtime.slots)
    {
        if (slot_state.session_id == session_id)
        {
            return &slot_state;
        }
    }

    return nullptr;
}

bool ActivateDedicatedLoopbackSession(
    EngineShimState& state,
    std::string_view session_id,
    bool count_surface_result,
    int* activated_slot,
    std::string* reject_reason)
{
    if (activated_slot != nullptr)
    {
        *activated_slot = 0;
    }
    if (reject_reason != nullptr)
    {
        reject_reason->clear();
    }

    DedicatedPlayerRuntimeSlot* slot_state = FindDedicatedPlayerRuntimeSlotBySession(
        state.dedicated_multiplayer_foundation,
        session_id);
    if (slot_state == nullptr)
    {
        if (count_surface_result)
        {
            ++state.dedicated_activation_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "unknown-session";
        }
        return false;
    }

    if (!slot_state->connected)
    {
        if (count_surface_result)
        {
            ++state.dedicated_activation_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "not-connected";
        }
        return false;
    }

    if (slot_state->put_in_server
        || slot_state->lifecycle_state == DedicatedPlayerLifecycleState::kSpawned
        || slot_state->lifecycle_state == DedicatedPlayerLifecycleState::kRespawned)
    {
        if (count_surface_result)
        {
            ++state.dedicated_activation_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "already-activated";
        }
        return false;
    }

    RecordDedicatedLifecycleTransition(
        state.dedicated_multiplayer_foundation,
        *slot_state,
        DedicatedPlayerLifecycleState::kPutInServer,
        "loopback post-connect activation promoted externally admitted session to put_in_server");

    Vector spawn_origin;
    std::string spawn_detail;
    TryResolveDedicatedSpawnOrigin(state, slot_state->slot - 1, &spawn_origin, &spawn_detail);
    ApplyDedicatedClientSpawn(state, *slot_state, spawn_origin);
    slot_state->last_origin = spawn_origin;
    slot_state->has_last_origin = true;
    RecordDedicatedLifecycleTransition(
        state.dedicated_multiplayer_foundation,
        *slot_state,
        DedicatedPlayerLifecycleState::kSpawned,
        "loopback post-connect activation spawned externally admitted session at " + spawn_detail);

    if (count_surface_result)
    {
        ++state.dedicated_activation_surface.accepted;
        ++state.dedicated_activation_surface.put_in_server;
        ++state.dedicated_activation_surface.spawned;
    }
    if (activated_slot != nullptr)
    {
        *activated_slot = slot_state->slot;
    }
    return true;
}

bool BootstrapDedicatedLoopbackSession(
    EngineShimState& state,
    std::string_view session_id,
    bool count_surface_result,
    int* bootstrapped_slot,
    std::string* reject_reason)
{
    if (bootstrapped_slot != nullptr)
    {
        *bootstrapped_slot = 0;
    }
    if (reject_reason != nullptr)
    {
        reject_reason->clear();
    }

    DedicatedPlayerRuntimeSlot* slot_state = FindDedicatedPlayerRuntimeSlotBySession(
        state.dedicated_multiplayer_foundation,
        session_id);
    if (slot_state == nullptr)
    {
        if (count_surface_result)
        {
            ++state.dedicated_bootstrap_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "unknown-session";
        }
        return false;
    }

    if (!slot_state->external_loopback_admission)
    {
        if (count_surface_result)
        {
            ++state.dedicated_bootstrap_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "not-external-admission";
        }
        return false;
    }

    if (!slot_state->connected
        || !slot_state->put_in_server
        || !slot_state->alive
        || slot_state->spawn_count <= 0)
    {
        if (count_surface_result)
        {
            ++state.dedicated_bootstrap_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "not-activated";
        }
        return false;
    }

    if (slot_state->bootstrap_delivered)
    {
        if (count_surface_result)
        {
            ++state.dedicated_bootstrap_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = "already-bootstrapped";
        }
        return false;
    }

    RecordDedicatedLifecycleTransition(
        state.dedicated_multiplayer_foundation,
        *slot_state,
        DedicatedPlayerLifecycleState::kSignonReady,
        "loopback bootstrap descriptor request marked activated external session signon_ready");
    RecordDedicatedLifecycleTransition(
        state.dedicated_multiplayer_foundation,
        *slot_state,
        DedicatedPlayerLifecycleState::kBootstrapDelivered,
        "loopback bootstrap descriptor delivered; full signon stream intentionally pending");

    if (count_surface_result)
    {
        ++state.dedicated_bootstrap_surface.accepted;
        ++state.dedicated_bootstrap_surface.signon_ready;
        ++state.dedicated_bootstrap_surface.bootstrap_delivered;
    }
    if (bootstrapped_slot != nullptr)
    {
        *bootstrapped_slot = slot_state->slot;
    }
    return true;
}

bool AdvanceDedicatedLoopbackBootstrapSequenceStep(
    EngineShimState& state,
    std::string_view session_id,
    int requested_step,
    bool count_surface_result,
    int* sequenced_slot,
    std::string* reject_reason)
{
    static constexpr int kBootstrapSequenceSteps = 3;
    static constexpr int kBootstrapSequenceFinalStep = kBootstrapSequenceSteps - 1;

    if (sequenced_slot != nullptr)
    {
        *sequenced_slot = 0;
    }
    if (reject_reason != nullptr)
    {
        reject_reason->clear();
    }

    const auto reject = [&](std::string reason) -> bool
    {
        if (count_surface_result)
        {
            ++state.dedicated_bootstrap_sequence_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = std::move(reason);
        }
        return false;
    };

    DedicatedPlayerRuntimeSlot* slot_state = FindDedicatedPlayerRuntimeSlotBySession(
        state.dedicated_multiplayer_foundation,
        session_id);
    if (slot_state == nullptr)
    {
        return reject("unknown-session");
    }

    if (!slot_state->external_loopback_admission)
    {
        return reject("not-external-admission");
    }

    if (!slot_state->connected
        || !slot_state->put_in_server
        || !slot_state->alive
        || slot_state->spawn_count <= 0)
    {
        return reject("not-activated");
    }

    if (!slot_state->signon_ready || !slot_state->bootstrap_delivered)
    {
        return reject("not-bootstrapped");
    }

    if (slot_state->bootstrap_sequence_completed)
    {
        return reject("already-sequenced");
    }

    if (requested_step < 0 || requested_step >= kBootstrapSequenceSteps)
    {
        return reject("invalid-step");
    }

    if (requested_step != slot_state->bootstrap_sequence_next_step)
    {
        return reject("unexpected-step");
    }

    if (requested_step < kBootstrapSequenceFinalStep)
    {
        ++slot_state->bootstrap_sequence_next_step;
        if (sequenced_slot != nullptr)
        {
            *sequenced_slot = slot_state->slot;
        }
        return true;
    }

    RecordDedicatedLifecycleTransition(
        state.dedicated_multiplayer_foundation,
        *slot_state,
        DedicatedPlayerLifecycleState::kBaselineReady,
        "loopback ordered bootstrap-sequence final descriptor marked bounded baseline_ready");
    RecordDedicatedLifecycleTransition(
        state.dedicated_multiplayer_foundation,
        *slot_state,
        DedicatedPlayerLifecycleState::kBootstrapSequenceCompleted,
        "loopback ordered bootstrap-sequence completed; real baselines/snapshots intentionally pending");
    slot_state->bootstrap_sequence_next_step = kBootstrapSequenceSteps;

    if (count_surface_result)
    {
        ++state.dedicated_bootstrap_sequence_surface.accepted;
    }
    if (sequenced_slot != nullptr)
    {
        *sequenced_slot = slot_state->slot;
    }
    return true;
}

