bool AdvanceDedicatedLoopbackSignonStreamWindow(
    EngineShimState& state,
    std::string_view session_id,
    int requested_window,
    bool count_surface_result,
    int* window_slot,
    bool* replay_accepted,
    std::string* reject_reason)
{
    static constexpr int kSignonStreamWindowCount = 2;
    static constexpr int kSignonFinalWindow = kSignonStreamWindowCount - 1;

    if (window_slot != nullptr)
    {
        *window_slot = 0;
    }
    if (replay_accepted != nullptr)
    {
        *replay_accepted = false;
    }
    if (reject_reason != nullptr)
    {
        reject_reason->clear();
    }

    const auto reject = [&](std::string reason) -> bool
    {
        if (count_surface_result)
        {
            ++state.dedicated_signon_stream_window_surface.rejected;
        }
        if (reject_reason != nullptr)
        {
            *reject_reason = std::move(reason);
        }
        return false;
    };

    DedicatedPlayerRuntimeSlot* slot_state = FindDedicatedPlayerRuntimeSlotBySession(
        state.dedicated_multiplayer_foundation,
        session_id);
    if (slot_state == nullptr)
    {
        return reject("unknown-session");
    }

    if (!slot_state->external_loopback_admission)
    {
        return reject("not-external-admission");
    }

    if (!slot_state->connected
        || !slot_state->put_in_server
        || !slot_state->alive
        || slot_state->spawn_count <= 0)
    {
        return reject("not-activated");
    }

    if (!slot_state->signon_ready || !slot_state->bootstrap_delivered)
    {
        return reject("not-bootstrapped");
    }

    if (!slot_state->baseline_ready || !slot_state->bootstrap_sequence_completed)
    {
        return reject("not-sequenced");
    }

    if (!slot_state->signon_catalog_ready || !slot_state->bootstrap_records_staged)
    {
        return reject("not-cataloged");
    }

    if (!slot_state->signon_template_ready || !slot_state->template_records_delivered)
    {
        return reject("not-initially-templated");
    }

    if (!slot_state->signon_template_coverage_complete
        || !slot_state->remaining_template_records_delivered)
    {
        return reject("template-coverage-incomplete");
    }

    if (!slot_state->signon_envelope_ready || !slot_state->framed_template_records_delivered)
    {
        return reject("envelope-incomplete");
    }

    if (!slot_state->signon_batch_ready || !slot_state->pseudo_packet_batch_delivered)
    {
        return reject("not-batch-ready");
    }

    if (!slot_state->signon_wiremap_ready || !slot_state->wiremapped_batch_delivered)
    {
        return reject("not-wiremap-ready");
    }

    if (!slot_state->signon_burst_ready || !slot_state->pseudo_wire_burst_delivered)
    {
        return reject("not-burst-ready");
    }

    if (!slot_state->signon_stream_ready || !slot_state->contiguous_stream_delivered)
    {
        return reject("not-stream-ready");
    }

    if (requested_window < 0 || requested_window >= kSignonStreamWindowCount)
    {
        return reject("invalid-window");
    }

    const unsigned int requested_window_bit = 1u << requested_window;
    const bool already_delivered =
        (slot_state->signon_stream_window_delivered_mask & requested_window_bit) != 0u;

    if (requested_window == slot_state->signon_stream_window_next_window)
    {
        slot_state->signon_stream_window_delivered_mask |= requested_window_bit;

        if (requested_window < kSignonFinalWindow)
        {
            ++slot_state->signon_stream_window_next_window;
        }
        else
        {
            RecordDedicatedLifecycleTransition(
                state.dedicated_multiplayer_foundation,
                *slot_state,
                DedicatedPlayerLifecycleState::kSignonStreamWindowReady,
                "loopback ordered signon stream window flow marked stream-ready external session signon_stream_window_ready");
            RecordDedicatedLifecycleTransition(
                state.dedicated_multiplayer_foundation,
                *slot_state,
                DedicatedPlayerLifecycleState::kWindowedStreamDelivered,
                "loopback ordered bounded signon stream windows delivered contiguous stream halves with one post-flow idempotent replay allowance; real signon wire compatibility intentionally pending");
            slot_state->signon_stream_window_next_window = kSignonStreamWindowCount;
        }

        if (count_surface_result)
        {
            ++state.dedicated_signon_stream_window_surface.accepted;
        }
        if (window_slot != nullptr)
        {
            *window_slot = slot_state->slot;
        }
        return true;
    }

    if (already_delivered && slot_state->windowed_stream_delivered)
    {
        if (slot_state->signon_stream_window_replay_used)
        {
            return reject("replay-limit-reached");
        }

        slot_state->signon_stream_window_replay_used = true;
        ++slot_state->signon_stream_window_replays_accepted;
        if (count_surface_result)
        {
            ++state.dedicated_signon_stream_window_surface.accepted;
            ++state.dedicated_signon_stream_window_surface.replays_accepted;
        }
        if (window_slot != nullptr)
        {
            *window_slot = slot_state->slot;
        }
        if (replay_accepted != nullptr)
        {
            *replay_accepted = true;
        }
        return true;
    }

    return reject(
        already_delivered && slot_state->windowed_stream_delivered
            ? "replay-limit-reached"
            : "unexpected-window");
}

