    const int requested_count =
        claimant_slot
            ->last_message_cursor_carried_checkpoint_claimed_checkpoint_resume_range_requested_message_count;
    const int next_start_after_resume_fetch =
        claimant_slot
            ->last_message_cursor_carried_checkpoint_claimed_checkpoint_resume_range_next_start_message_index;
    const int remaining_after_resume_fetch =
        claimant_slot
            ->last_message_cursor_carried_checkpoint_claimed_checkpoint_resume_range_remaining_message_count;
