std::vector<unsigned char> BuildGoldSrcInfoRequest()
{
    static constexpr std::array<unsigned char, 25> kRequest = {{
        0xFFu, 0xFFu, 0xFFu, 0xFFu,
        'T',
        'S', 'o', 'u', 'r', 'c', 'e', ' ', 'E', 'n', 'g', 'i', 'n', 'e', ' ',
        'Q', 'u', 'e', 'r', 'y',
        0x00u,
    }};

    return std::vector<unsigned char>(kRequest.begin(), kRequest.end());
}

bool IsGoldSrcInfoRequest(const unsigned char* data, int size)
{
    const std::vector<unsigned char> expected = BuildGoldSrcInfoRequest();
    return size == static_cast<int>(expected.size())
        && std::equal(expected.begin(), expected.end(), data);
}

void AppendGoldSrcCString(std::vector<unsigned char>& bytes, std::string_view value)
{
    bytes.insert(bytes.end(), value.begin(), value.end());
    bytes.push_back(0x00u);
}

std::vector<unsigned char> BuildGoldSrcInfoResponse(
    const hl::game_api::DedicatedQuerySurfaceSummary& surface)
{
    std::vector<unsigned char> bytes;
    bytes.reserve(192);
    bytes.push_back(0xFFu);
    bytes.push_back(0xFFu);
    bytes.push_back(0xFFu);
    bytes.push_back(0xFFu);
    bytes.push_back('m');
    AppendGoldSrcCString(
        bytes,
        "127.0.0.1:" + std::to_string(surface.bound_port));
    AppendGoldSrcCString(bytes, surface.server_name.empty() ? "HLengine Test Server" : surface.server_name);
    AppendGoldSrcCString(bytes, surface.map_name.empty() ? "c0a0" : surface.map_name);
    AppendGoldSrcCString(bytes, surface.mod_name.empty() ? "valve" : surface.mod_name);
    AppendGoldSrcCString(bytes, surface.ruleset == "hldm" ? "Half-Life Deathmatch" : "Half-Life");
    bytes.push_back(static_cast<unsigned char>(std::max(0, std::min(surface.players, 255))));
    bytes.push_back(static_cast<unsigned char>(std::max(0, std::min(surface.max_players, 255))));
    bytes.push_back(48u);
    bytes.push_back('d');
    bytes.push_back('w');
    bytes.push_back(0u);
    bytes.push_back(0u);
    bytes.push_back(0u);
    return bytes;
}

bool ReadGoldSrcCString(
    const std::vector<unsigned char>& bytes,
    std::size_t* offset,
    std::string* value)
{
    if (offset == nullptr || value == nullptr || *offset >= bytes.size())
    {
        return false;
    }

    const std::size_t start = *offset;
    while (*offset < bytes.size() && bytes[*offset] != 0x00u)
    {
        ++(*offset);
    }

    if (*offset >= bytes.size())
    {
        return false;
    }

    *value = std::string(
        reinterpret_cast<const char*>(bytes.data() + start),
        *offset - start);
    ++(*offset);
    return true;
}

bool ParseGoldSrcInfoResponse(
    const std::vector<unsigned char>& bytes,
    hl::game_api::DedicatedQueryProbeSummary* probe)
{
    if (probe == nullptr || bytes.size() < 5
        || bytes[0] != 0xFFu
        || bytes[1] != 0xFFu
        || bytes[2] != 0xFFu
        || bytes[3] != 0xFFu
        || bytes[4] != static_cast<unsigned char>('m'))
    {
        return false;
    }

    std::size_t offset = 5;
    std::string address;
    std::string game_directory;
    std::string game_description;
    if (!ReadGoldSrcCString(bytes, &offset, &address)
        || !ReadGoldSrcCString(bytes, &offset, &probe->parsed_name)
        || !ReadGoldSrcCString(bytes, &offset, &probe->parsed_map)
        || !ReadGoldSrcCString(bytes, &offset, &game_directory)
        || !ReadGoldSrcCString(bytes, &offset, &game_description)
        || offset + 2 > bytes.size())
    {
        return false;
    }

    probe->parsed_players = static_cast<int>(bytes[offset++]);
    probe->parsed_max_players = static_cast<int>(bytes[offset++]);
    (void)address;
    (void)game_directory;
    (void)game_description;
    return true;
}

std::vector<unsigned char> BuildConnectionlessTextPacket(std::string_view text)
{
    std::vector<unsigned char> bytes;
    bytes.reserve(text.size() + 5);
    bytes.push_back(0xFFu);
    bytes.push_back(0xFFu);
    bytes.push_back(0xFFu);
    bytes.push_back(0xFFu);
    bytes.insert(bytes.end(), text.begin(), text.end());
    bytes.push_back(0x00u);
    return bytes;
}

std::string ExtractConnectionlessText(const unsigned char* data, int size)
{
    if (data == nullptr || size < 5
        || data[0] != 0xFFu
        || data[1] != 0xFFu
        || data[2] != 0xFFu
        || data[3] != 0xFFu)
    {
        return {};
    }

    int end = size;
    while (end > 4 && data[end - 1] == 0x00u)
    {
        --end;
    }

    return std::string(
        reinterpret_cast<const char*>(data + 4),
        static_cast<std::size_t>(std::max(0, end - 4)));
}

bool ParseChallengeResponseText(std::string_view text, int* challenge)
{
    static constexpr std::string_view kPrefix = "challenge ";
    if (challenge == nullptr || !StartsWithText(text, kPrefix))
    {
        return false;
    }

    const std::string_view challenge_text = text.substr(kPrefix.size());
    const char* begin = challenge_text.data();
    const char* end = challenge_text.data() + challenge_text.size();
    int parsed = 0;
    const std::from_chars_result result = std::from_chars(begin, end, parsed);
    if (result.ec != std::errc{} || result.ptr != end)
    {
        return false;
    }

    *challenge = parsed;
    return true;
}

bool ParseAcceptResponseText(
    std::string_view text,
    int* players,
    int* max_players,
    int* accepted_slot)
{
    if (!StartsWithText(text, "accept "))
    {
        return false;
    }

    const std::string slot_text = ExtractTokenValue(text, "slot=");
    const std::string players_text = ExtractTokenValue(text, "players=");
    const std::string max_text = ExtractTokenValue(text, "max=");
    if (slot_text.empty() || players_text.empty() || max_text.empty())
    {
        return false;
    }
    const int parsed_slot = std::atoi(slot_text.c_str());
    const int parsed_players = std::atoi(players_text.c_str());
    const int parsed_max_players = std::atoi(max_text.c_str());

    if (players != nullptr)
    {
        *players = parsed_players;
    }
    if (max_players != nullptr)
    {
        *max_players = parsed_max_players;
    }
    if (accepted_slot != nullptr)
    {
        *accepted_slot = parsed_slot;
    }
    return true;
}

bool ParseRejectResponseText(
    std::string_view text,
    std::string* reason,
    int* players,
    int* max_players)
{
    static constexpr std::string_view kPrefix = "reject reason=";
    if (!StartsWithText(text, kPrefix))
    {
        return false;
    }

    const std::size_t players_marker = text.find(" players=");
    const std::size_t max_marker = text.find(" max=");
    if (players_marker == std::string_view::npos
        || max_marker == std::string_view::npos
        || max_marker <= players_marker)
    {
        return false;
    }

    if (reason != nullptr)
    {
        *reason = std::string(text.substr(kPrefix.size(), players_marker - kPrefix.size()));
    }

    const std::string players_text(
        text.substr(players_marker + 9, max_marker - (players_marker + 9)));
    const std::string max_text(text.substr(max_marker + 5));
    if (players != nullptr)
    {
        *players = std::atoi(players_text.c_str());
    }
    if (max_players != nullptr)
    {
        *max_players = std::atoi(max_text.c_str());
    }
    return true;
}

