void AppendByteLengthPrefixedText(
    std::vector<unsigned char>& bytes,
    std::string_view value)
{
    const std::size_t clamped_size = std::min<std::size_t>(value.size(), 255);
    bytes.push_back(static_cast<unsigned char>(clamped_size));
    bytes.insert(bytes.end(), value.begin(), value.begin() + static_cast<std::ptrdiff_t>(clamped_size));
}

void AppendLittleEndianShort(std::vector<unsigned char>& bytes, unsigned int value)
{
    bytes.push_back(static_cast<unsigned char>(value & 0xFFu));
    bytes.push_back(static_cast<unsigned char>((value >> 8) & 0xFFu));
}

std::string EncodeUpperHex(const std::vector<unsigned char>& bytes)
{
    std::ostringstream stream;
    stream << std::uppercase << std::hex << std::setfill('0');
    for (const unsigned char value : bytes)
    {
        stream << std::setw(2) << static_cast<int>(value);
    }
    return stream.str();
}

int HexNibbleValue(char value)
{
    if (value >= '0' && value <= '9')
    {
        return value - '0';
    }
    if (value >= 'A' && value <= 'F')
    {
        return value - 'A' + 10;
    }
    if (value >= 'a' && value <= 'f')
    {
        return value - 'a' + 10;
    }
    return -1;
}

bool TryDecodeUpperHex(
    std::string_view text,
    std::vector<unsigned char>* bytes)
{
    if (bytes == nullptr || (text.size() % 2) != 0)
    {
        return false;
    }

    bytes->clear();
    bytes->reserve(text.size() / 2);
    for (std::size_t index = 0; index < text.size(); index += 2)
    {
        const int high = HexNibbleValue(text[index]);
        const int low = HexNibbleValue(text[index + 1]);
        if (high < 0 || low < 0)
        {
            bytes->clear();
            return false;
        }

        bytes->push_back(static_cast<unsigned char>((high << 4) | low));
    }

    return true;
}

std::vector<unsigned char> BuildDedicatedSignonTemplateBytes(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state,
    int requested_template)
{
    std::vector<unsigned char> bytes;
    const std::string map_name =
        state.server_state.map_name.empty() ? std::string("c0a0") : state.server_state.map_name;
    const std::string ruleset = DedicatedRulesetName(state.server_state);
    const std::string player_name =
        slot_state.player_name.empty() ? std::string("loopback_player") : slot_state.player_name;
    const std::string last_origin =
        slot_state.has_last_origin ? FormatVector(slot_state.last_origin) : std::string("<unset>");

    switch (requested_template)
    {
    case 0:
        bytes.reserve(32 + slot_state.session_id.size() + map_name.size() + ruleset.size());
        bytes.push_back('H');
        bytes.push_back('L');
        bytes.push_back('T');
        bytes.push_back('0');
        bytes.push_back(static_cast<unsigned char>(std::max(slot_state.slot, 0)));
        bytes.push_back(static_cast<unsigned char>(std::max(state.server_state.maxclients, 0)));
        bytes.push_back(static_cast<unsigned char>(state.server_state.deathmatch != 0.0f ? 1 : 0));
        bytes.push_back(static_cast<unsigned char>(state.server_state.coop != 0.0f ? 1 : 0));
        bytes.push_back(static_cast<unsigned char>(slot_state.spawn_count > 0 ? 1 : 0));
        AppendByteLengthPrefixedText(bytes, slot_state.session_id);
        AppendByteLengthPrefixedText(bytes, map_name);
        AppendByteLengthPrefixedText(bytes, ruleset);
        break;
    case 1:
        bytes.reserve(24 + state.server_state.mod_name.size());
        bytes.push_back('H');
        bytes.push_back('L');
        bytes.push_back('T');
        bytes.push_back('1');
        AppendLittleEndianShort(
            bytes,
            static_cast<unsigned int>(state.precache_registry.ModelCount()));
        AppendLittleEndianShort(
            bytes,
            static_cast<unsigned int>(state.sound_precache_registry.RegistrySize()));
        AppendLittleEndianShort(
            bytes,
            static_cast<unsigned int>(state.generic_precache_registry.Size()));
        AppendLittleEndianShort(
            bytes,
            static_cast<unsigned int>(state.event_precache_registry.Size()));
        AppendLittleEndianShort(
            bytes,
            static_cast<unsigned int>(state.decal_registry.Size()));
        AppendLittleEndianShort(
            bytes,
            static_cast<unsigned int>(state.user_message_registry.Size()));
        AppendByteLengthPrefixedText(bytes, state.server_state.mod_name);
        break;
    case 2:
        bytes.reserve(48 + slot_state.session_id.size() + player_name.size() + last_origin.size());
        bytes.push_back('H');
        bytes.push_back('L');
        bytes.push_back('T');
        bytes.push_back('2');
        bytes.push_back(static_cast<unsigned char>(std::max(slot_state.slot, 0)));
        bytes.push_back(static_cast<unsigned char>(slot_state.spawn_count > 0 ? 1 : 0));
        bytes.push_back(static_cast<unsigned char>(std::max(slot_state.spawn_count, 0)));
        bytes.push_back(static_cast<unsigned char>(std::max(slot_state.respawn_count, 0)));
        AppendLittleEndianShort(
            bytes,
            static_cast<unsigned int>(std::max(slot_state.death_count, 0)));
        AppendByteLengthPrefixedText(bytes, slot_state.session_id);
        AppendByteLengthPrefixedText(bytes, player_name);
        AppendByteLengthPrefixedText(bytes, last_origin);
        break;
    case 3:
        bytes.reserve(40 + slot_state.session_id.size() + map_name.size() + ruleset.size());
        bytes.push_back('H');
        bytes.push_back('L');
        bytes.push_back('T');
        bytes.push_back('3');
        bytes.push_back(4u);
        bytes.push_back(2u);
        bytes.push_back(static_cast<unsigned char>(slot_state.bootstrap_records_staged ? 1 : 0));
        bytes.push_back(static_cast<unsigned char>(slot_state.signon_template_ready ? 1 : 0));
        bytes.push_back(static_cast<unsigned char>(slot_state.template_records_delivered ? 1 : 0));
        bytes.push_back(
            static_cast<unsigned char>(slot_state.signon_template_coverage_complete ? 1 : 0));
        bytes.push_back(static_cast<unsigned char>(
            slot_state.remaining_template_records_delivered ? 1 : 0));
        AppendByteLengthPrefixedText(bytes, slot_state.session_id);
        AppendByteLengthPrefixedText(bytes, map_name);
        AppendByteLengthPrefixedText(bytes, ruleset);
        break;
    default:
        break;
    }

    return bytes;
}

std::vector<unsigned char> BuildDedicatedSignonEnvelopeFrameBytes(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state,
    int requested_frame)
{
    static constexpr unsigned char kTotalFrameCount = 4u;
    std::vector<unsigned char> payload =
        BuildDedicatedSignonTemplateBytes(state, slot_state, requested_frame);
    if (payload.empty())
    {
        return {};
    }

    std::vector<unsigned char> bytes;
    bytes.reserve(9 + payload.size());
    bytes.push_back('H');
    bytes.push_back('L');
    bytes.push_back('E');
    bytes.push_back('F');
    bytes.push_back(static_cast<unsigned char>(std::max(requested_frame, 0)));
    bytes.push_back(static_cast<unsigned char>(std::max(requested_frame, 0)));
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(payload.size()));
    bytes.push_back(kTotalFrameCount);
    bytes.insert(bytes.end(), payload.begin(), payload.end());
    return bytes;
}

std::vector<unsigned char> BuildDedicatedSignonBatchPacketBytes(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state,
    int requested_packet)
{
    static constexpr unsigned char kTotalPacketCount = 2u;
    static constexpr int kFramesPerPacket = 2;
    static constexpr int kTotalFrameCount = 4;

    if (requested_packet < 0 || requested_packet >= static_cast<int>(kTotalPacketCount))
    {
        return {};
    }

    const int first_frame = requested_packet * kFramesPerPacket;
    const int last_frame = std::min(first_frame + (kFramesPerPacket - 1), kTotalFrameCount - 1);

    std::vector<unsigned char> payload;
    for (int frame_index = first_frame; frame_index <= last_frame; ++frame_index)
    {
        std::vector<unsigned char> frame_bytes =
            BuildDedicatedSignonEnvelopeFrameBytes(state, slot_state, frame_index);
        if (frame_bytes.empty())
        {
            return {};
        }

        payload.insert(payload.end(), frame_bytes.begin(), frame_bytes.end());
    }

    std::vector<unsigned char> bytes;
    bytes.reserve(10 + payload.size());
    bytes.push_back('H');
    bytes.push_back('L');
    bytes.push_back('P');
    bytes.push_back('B');
    bytes.push_back(static_cast<unsigned char>(requested_packet));
    bytes.push_back(kTotalPacketCount);
    bytes.push_back(static_cast<unsigned char>(first_frame));
    bytes.push_back(static_cast<unsigned char>(last_frame));
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(payload.size()));
    bytes.insert(bytes.end(), payload.begin(), payload.end());
    return bytes;
}

unsigned short DedicatedSignonWiremapSequenceId(int requested_packet)
{
    return static_cast<unsigned short>(0x1200u + static_cast<unsigned int>(std::max(requested_packet, 0)));
}

unsigned short DedicatedSignonWiremapFlags(int requested_packet)
{
    unsigned short flags = 0u;
    if (requested_packet == 0)
    {
        flags |= 0x0001u;
    }
    if (requested_packet == 1)
    {
        flags |= 0x0002u;
    }
    return flags;
}

std::string_view DedicatedSignonWiremapMessageKind()
{
    return "pseudo-packet-body";
}

std::vector<unsigned char> BuildDedicatedSignonWiremapPacketBytes(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state,
    int requested_packet)
{
    const std::vector<unsigned char> batch_bytes =
        BuildDedicatedSignonBatchPacketBytes(state, slot_state, requested_packet);
    if (batch_bytes.empty())
    {
        return {};
    }

    const unsigned short sequence_id = DedicatedSignonWiremapSequenceId(requested_packet);
    const unsigned short flags = DedicatedSignonWiremapFlags(requested_packet);
    const std::string_view message_kind = DedicatedSignonWiremapMessageKind();

    std::vector<unsigned char> bytes;
    bytes.reserve(13 + message_kind.size() + batch_bytes.size());
    bytes.push_back('H');
    bytes.push_back('L');
    bytes.push_back('W');
    bytes.push_back('M');
    bytes.push_back(static_cast<unsigned char>(std::max(requested_packet, 0)));
    bytes.push_back(2u);
    AppendLittleEndianShort(bytes, sequence_id);
    AppendLittleEndianShort(bytes, flags);
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(batch_bytes.size()));
    bytes.push_back(static_cast<unsigned char>(message_kind.size()));
    bytes.insert(bytes.end(), message_kind.begin(), message_kind.end());
    bytes.insert(bytes.end(), batch_bytes.begin(), batch_bytes.end());
    return bytes;
}

std::vector<unsigned char> BuildDedicatedSignonBurstBytes(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state,
    int requested_burst)
{
    static constexpr unsigned char kTotalBurstCount = 1u;
    static constexpr unsigned char kPacketCount = 2u;
    static constexpr unsigned char kFirstPacketIndex = 0u;
    static constexpr unsigned char kLastPacketIndex = 1u;

    if (requested_burst < 0 || requested_burst >= static_cast<int>(kTotalBurstCount))
    {
        return {};
    }

    std::vector<unsigned char> payload;
    for (int packet_index = static_cast<int>(kFirstPacketIndex);
         packet_index <= static_cast<int>(kLastPacketIndex);
         ++packet_index)
    {
        std::vector<unsigned char> mapping_bytes =
            BuildDedicatedSignonWiremapPacketBytes(state, slot_state, packet_index);
        if (mapping_bytes.empty())
        {
            return {};
        }

        payload.insert(payload.end(), mapping_bytes.begin(), mapping_bytes.end());
    }

    std::vector<unsigned char> bytes;
    bytes.reserve(11 + payload.size());
    bytes.push_back('H');
    bytes.push_back('L');
    bytes.push_back('W');
    bytes.push_back('B');
    bytes.push_back(static_cast<unsigned char>(requested_burst));
    bytes.push_back(kTotalBurstCount);
    bytes.push_back(kPacketCount);
    bytes.push_back(kFirstPacketIndex);
    bytes.push_back(kLastPacketIndex);
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(payload.size()));
    bytes.insert(bytes.end(), payload.begin(), payload.end());
    return bytes;
}

std::vector<unsigned char> BuildDedicatedSignonStreamBytes(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state,
    int requested_segment)
{
    static constexpr unsigned char kTotalSegmentCount = 1u;

    if (requested_segment < 0 || requested_segment >= static_cast<int>(kTotalSegmentCount))
    {
        return {};
    }

    const std::vector<unsigned char> burst_bytes =
        BuildDedicatedSignonBurstBytes(state, slot_state, 0);
    if (burst_bytes.size() < 11)
    {
        return {};
    }

    const std::vector<unsigned char> payload(burst_bytes.begin() + 11, burst_bytes.end());
    const unsigned int payload_size = static_cast<unsigned int>(payload.size());

    std::vector<unsigned char> bytes;
    bytes.reserve(12 + payload.size());
    bytes.push_back('H');
    bytes.push_back('L');
    bytes.push_back('W');
    bytes.push_back('S');
    bytes.push_back(static_cast<unsigned char>(requested_segment));
    bytes.push_back(kTotalSegmentCount);
    AppendLittleEndianShort(bytes, 0u);
    AppendLittleEndianShort(bytes, payload_size);
    AppendLittleEndianShort(bytes, payload_size);
    bytes.insert(bytes.end(), payload.begin(), payload.end());
    return bytes;
}

std::vector<unsigned char> BuildDedicatedSignonStreamWindowBytes(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state,
    int requested_window)
{
    static constexpr int kWindowCount = 2;

    if (requested_window < 0 || requested_window >= kWindowCount)
    {
        return {};
    }

    const std::vector<unsigned char> stream_bytes =
        BuildDedicatedSignonStreamBytes(state, slot_state, 0);
    if (stream_bytes.size() < 12)
    {
        return {};
    }

    const std::vector<unsigned char> payload(stream_bytes.begin() + 12, stream_bytes.end());
    const int final_stream_byte_length = static_cast<int>(payload.size());
    if (final_stream_byte_length <= 0)
    {
        return {};
    }

    const int first_window_length = (final_stream_byte_length + 1) / 2;
    const int second_window_length = final_stream_byte_length - first_window_length;
    const int stream_offset = requested_window == 0 ? 0 : first_window_length;
    const int window_byte_length =
        requested_window == 0 ? first_window_length : second_window_length;
    if (window_byte_length <= 0
        || (stream_offset + window_byte_length) > final_stream_byte_length)
    {
        return {};
    }

    std::vector<unsigned char> bytes;
    bytes.reserve(12 + static_cast<std::size_t>(window_byte_length));
    bytes.push_back('H');
    bytes.push_back('L');
    bytes.push_back('W');
    bytes.push_back('W');
    bytes.push_back(static_cast<unsigned char>(requested_window));
    bytes.push_back(static_cast<unsigned char>(kWindowCount));
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(stream_offset));
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(window_byte_length));
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(final_stream_byte_length));
    bytes.insert(
        bytes.end(),
        payload.begin() + stream_offset,
        payload.begin() + stream_offset + window_byte_length);
    return bytes;
}

std::vector<DedicatedSignonMessageBoundaryDescriptor> BuildDedicatedSignonMessageBoundaries(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state)
{
    static constexpr std::array<std::string_view, 4> kSemanticTags = {{
        "server-map-rules-slot-content",
        "resource-precache-summary-content",
        "player-session-spawn-baseline-summary-content",
        "completion-staged-records-ready-content",
    }};

    const std::vector<unsigned char> stream_bytes =
        BuildDedicatedSignonStreamBytes(state, slot_state, 0);
    if (stream_bytes.size() < 12)
    {
        return {};
    }

    const std::vector<unsigned char> payload(stream_bytes.begin() + 12, stream_bytes.end());
    std::vector<int> frame_offsets;
    frame_offsets.reserve(kSemanticTags.size());
    for (std::size_t index = 0; index + 3 < payload.size(); ++index)
    {
        if (payload[index] == 'H'
            && payload[index + 1] == 'L'
            && payload[index + 2] == 'E'
            && payload[index + 3] == 'F')
        {
            frame_offsets.push_back(static_cast<int>(index));
        }
    }

    if (frame_offsets.size() != kSemanticTags.size())
    {
        return {};
    }

    std::vector<DedicatedSignonMessageBoundaryDescriptor> descriptors;
    descriptors.reserve(kSemanticTags.size());
    for (std::size_t message_index = 0; message_index < kSemanticTags.size(); ++message_index)
    {
        const int start_offset = frame_offsets[message_index];
        const int end_offset =
            message_index + 1 < frame_offsets.size()
            ? frame_offsets[message_index + 1] - 1
            : static_cast<int>(payload.size()) - 1;
        if (start_offset < 0 || end_offset < start_offset)
        {
            return {};
        }

        descriptors.push_back({
            static_cast<int>(message_index),
            start_offset,
            end_offset,
            (end_offset - start_offset) + 1,
            std::string(kSemanticTags[message_index]),
        });
    }

    return descriptors;
}

std::vector<unsigned char> BuildDedicatedSignonMessageFetchBytes(
    const EngineShimState& state,
    const DedicatedPlayerRuntimeSlot& slot_state,
    int requested_message_index,
    DedicatedSignonMessageBoundaryDescriptor* descriptor)
{
    if (descriptor != nullptr)
    {
        *descriptor = {};
    }

    const std::vector<DedicatedSignonMessageBoundaryDescriptor> descriptors =
        BuildDedicatedSignonMessageBoundaries(state, slot_state);
    if (requested_message_index < 0
        || requested_message_index >= static_cast<int>(descriptors.size()))
    {
        return {};
    }

    const std::vector<unsigned char> stream_bytes =
        BuildDedicatedSignonStreamBytes(state, slot_state, 0);
    if (stream_bytes.size() < 12)
    {
        return {};
    }

    const std::vector<unsigned char> payload(stream_bytes.begin() + 12, stream_bytes.end());
    const DedicatedSignonMessageBoundaryDescriptor& selected =
        descriptors[static_cast<std::size_t>(requested_message_index)];
    if (selected.start_offset < 0
        || selected.end_offset < selected.start_offset
        || selected.byte_length <= 0
        || selected.end_offset >= static_cast<int>(payload.size()))
    {
        return {};
    }

    if (descriptor != nullptr)
    {
        *descriptor = selected;
    }

    std::vector<unsigned char> bytes;
    bytes.reserve(11 + static_cast<std::size_t>(selected.byte_length));
    bytes.push_back('H');
    bytes.push_back('L');
    bytes.push_back('W');
    bytes.push_back('M');
    bytes.push_back(static_cast<unsigned char>(requested_message_index));
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(selected.start_offset));
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(selected.end_offset));
    AppendLittleEndianShort(bytes, static_cast<unsigned int>(selected.byte_length));
    bytes.insert(
        bytes.end(),
        payload.begin() + selected.start_offset,
        payload.begin() + selected.end_offset + 1);
    return bytes;
}

std::string BuildDedicatedSignonMessageBoundaryCatalogToken(
    const std::vector<DedicatedSignonMessageBoundaryDescriptor>& descriptors)
{
    std::string token;
    for (std::size_t index = 0; index < descriptors.size(); ++index)
    {
        if (!token.empty())
        {
            token += "|";
        }

        const DedicatedSignonMessageBoundaryDescriptor& descriptor = descriptors[index];
        token += std::to_string(descriptor.message_index)
            + ":" + std::to_string(descriptor.start_offset)
            + ":" + std::to_string(descriptor.end_offset)
            + ":" + std::to_string(descriptor.byte_length)
            + ":" + descriptor.semantic_tag;
    }

    return token;
}

bool ParseDedicatedSignonMessageBoundaryCatalogToken(
    std::string_view text,
    int* parsed_message_count,
    int* parsed_final_message,
    std::string* parsed_message_offsets,
    std::string* parsed_message_byte_lengths,
    std::string* parsed_semantic_tags)
{
    if (parsed_message_count != nullptr)
    {
        *parsed_message_count = 0;
    }
    if (parsed_final_message != nullptr)
    {
        *parsed_final_message = -1;
    }
    if (parsed_message_offsets != nullptr)
    {
        parsed_message_offsets->clear();
    }
    if (parsed_message_byte_lengths != nullptr)
    {
        parsed_message_byte_lengths->clear();
    }
    if (parsed_semantic_tags != nullptr)
    {
        parsed_semantic_tags->clear();
    }

    if (text.empty())
    {
        return false;
    }

    int expected_index = 0;
    std::size_t cursor = 0;
    while (cursor < text.size())
    {
        const std::size_t next_delimiter = text.find('|', cursor);
        const std::string_view entry =
            next_delimiter == std::string_view::npos
            ? text.substr(cursor)
            : text.substr(cursor, next_delimiter - cursor);
        if (entry.empty())
        {
            return false;
        }

        const std::size_t first = entry.find(':');
        const std::size_t second = first == std::string_view::npos
            ? std::string_view::npos
            : entry.find(':', first + 1);
        const std::size_t third = second == std::string_view::npos
            ? std::string_view::npos
            : entry.find(':', second + 1);
        const std::size_t fourth = third == std::string_view::npos
            ? std::string_view::npos
            : entry.find(':', third + 1);
        if (first == std::string_view::npos
            || second == std::string_view::npos
            || third == std::string_view::npos
            || fourth == std::string_view::npos)
        {
            return false;
        }

        const int message_index = std::atoi(std::string(entry.substr(0, first)).c_str());
        const int start_offset = std::atoi(std::string(entry.substr(first + 1, second - first - 1)).c_str());
        const int end_offset = std::atoi(std::string(entry.substr(second + 1, third - second - 1)).c_str());
        const int byte_length = std::atoi(std::string(entry.substr(third + 1, fourth - third - 1)).c_str());
        const std::string semantic_tag = std::string(entry.substr(fourth + 1));
        if (message_index != expected_index
            || start_offset < 0
            || end_offset < start_offset
            || byte_length != (end_offset - start_offset) + 1
            || semantic_tag.empty())
        {
            return false;
        }

        if (parsed_message_offsets != nullptr)
        {
            if (!parsed_message_offsets->empty())
            {
                *parsed_message_offsets += "|";
            }
            *parsed_message_offsets += std::to_string(start_offset)
                + "-" + std::to_string(end_offset);
        }
        if (parsed_message_byte_lengths != nullptr)
        {
            if (!parsed_message_byte_lengths->empty())
            {
                *parsed_message_byte_lengths += "|";
            }
            *parsed_message_byte_lengths += std::to_string(byte_length);
        }
        if (parsed_semantic_tags != nullptr)
        {
            if (!parsed_semantic_tags->empty())
            {
                *parsed_semantic_tags += "|";
            }
            *parsed_semantic_tags += semantic_tag;
        }

        ++expected_index;
        cursor = next_delimiter == std::string_view::npos ? text.size() : next_delimiter + 1;
    }

    if (parsed_message_count != nullptr)
    {
        *parsed_message_count = expected_index;
    }
    if (parsed_final_message != nullptr)
    {
        *parsed_final_message = expected_index - 1;
    }
    return expected_index > 0;
}

std::string BuildDedicatedSignonMessageRangeToken(int start_message_index, int message_count)
{
    if (start_message_index < 0 || message_count <= 0)
    {
        return {};
    }

    return "start=" + std::to_string(start_message_index)
        + ",count=" + std::to_string(message_count);
}

std::string BuildDedicatedOpaqueCarriedCheckpointResumeBridgeToken(
    std::string_view source_session_id,
    std::string_view target_session_id,
    std::string_view checkpoint_cursor_id,
    int current_start_message_index,
    int current_message_count,
    int next_start_message_index,
    int remaining_message_count)
{
    const std::string material = std::string(source_session_id)
        + "|" + std::string(target_session_id)
        + "|" + std::string(checkpoint_cursor_id)
        + "|" + std::to_string(current_start_message_index)
        + "|" + std::to_string(current_message_count)
        + "|" + std::to_string(next_start_message_index)
        + "|" + std::to_string(remaining_message_count)
        + "|future-resume-claim-only";

    std::uint64_t hash = 14695981039346656037ull;
    for (const unsigned char ch : material)
    {
        hash ^= static_cast<std::uint64_t>(ch);
        hash *= 1099511628211ull;
    }

    return "bridge_" + std::to_string(hash);
}

