bool PumpOneLoopbackSignonCatalogFlow(
    EngineShimState& state,
    SOCKET server_socket,
    int bound_port,
    std::string_view session_id,
    hl::game_api::DedicatedSignonCatalogProbeSummary* probe)
{
    for (int record = 0; record < 4; ++record)
    {
        if (!PumpOneLoopbackSignonCatalogRecordAttempt(
                state,
                server_socket,
                bound_port,
                session_id,
                record,
                true,
                probe))
        {
            return false;
        }
    }

    return probe != nullptr
        && probe->accepted > 0
        && probe->parsed_record_count >= 4
        && probe->parsed_final_record >= 3
        && probe->signon_catalog_ready > 0
        && probe->bootstrap_records_staged > 0;
}

bool PumpOneLoopbackSignonTemplateRecordAttempt(
    EngineShimState& state,
    SOCKET server_socket,
    int bound_port,
    std::string_view session_id,
    int requested_template,
    bool expect_accept,
    hl::game_api::DedicatedSignonTemplateProbeSummary* probe)
{
    static constexpr int kSignonTemplateRecords = 2;
    static constexpr int kSignonTemplateFinalRecord = kSignonTemplateRecords - 1;

    if (probe == nullptr)
    {
        return false;
    }

    ++probe->attempts;

    ScopedUdpSocket probe_socket(::socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP));
    if (!probe_socket.Valid())
    {
        probe->detail =
            "signon template probe socket() failed WSA=" + std::to_string(WSAGetLastError());
        return false;
    }

    const sockaddr_in server_address =
        MakeLoopbackAddress(static_cast<unsigned short>(bound_port));
    const std::string template_session =
        session_id.empty()
        ? std::string("invalid_signon_template_session")
        : std::string(session_id);
    if (!SendConnectionlessText(
            probe_socket.Get(),
            server_address,
            sizeof(server_address),
            "signon_template session=" + template_session
                + " template=" + std::to_string(requested_template),
            &probe->detail,
            "signon template probe request"))
    {
        return false;
    }

    sockaddr_in template_client_address{};
    int template_client_address_size = sizeof(template_client_address);
    std::string template_request;
    if (!ReceiveConnectionlessText(
            server_socket,
            &template_request,
            &template_client_address,
            &template_client_address_size,
            &probe->detail,
            "signon template surface receiver"))
    {
        return false;
    }

    if (!StartsWithText(template_request, "signon_template "))
    {
        probe->detail = "signon template surface received unexpected request: "
            + template_request;
        return false;
    }

    const std::string request_session = ExtractTokenValue(template_request, "session=");
    const std::string request_template_text = ExtractTokenValue(template_request, "template=");
    const int request_template =
        request_template_text.empty() ? -1 : std::atoi(request_template_text.c_str());

    int template_slot = 0;
    std::string reject_reason;
    const bool template_accepted = AdvanceDedicatedLoopbackSignonTemplateRecord(
        state,
        request_session,
        request_template,
        true,
        &template_slot,
        &reject_reason);

    RefreshDedicatedSignonTemplateSurfaceSnapshot(state);
    RefreshDedicatedSignonCatalogSurfaceSnapshot(state);
    RefreshDedicatedBootstrapSequenceSurfaceSnapshot(state);
    RefreshDedicatedBootstrapSurfaceSnapshot(state);
    RefreshDedicatedActivationSurfaceSnapshot(state);
    RefreshDedicatedConnectSurfaceSnapshot(state);
    RefreshDedicatedQuerySurfaceSnapshot(state);

    const DedicatedPlayerRuntimeSlot* slot_state = template_accepted
        ? FindDedicatedPlayerRuntimeSlotBySession(
            state.dedicated_multiplayer_foundation,
            request_session)
        : nullptr;
    const int players = CountDedicatedQueryPlayers(state.dedicated_multiplayer_foundation);
    const int max_players = state.server_state.maxclients;
    const std::vector<unsigned char> template_bytes =
        template_accepted && slot_state != nullptr
        ? BuildDedicatedSignonTemplateBytes(state, *slot_state, request_template)
        : std::vector<unsigned char>();
    const std::string template_response =
        template_accepted && slot_state != nullptr && !template_bytes.empty()
        ? "signon_template session=" + request_session
            + " template=" + std::to_string(request_template)
            + " templateCount=" + std::to_string(kSignonTemplateRecords)
            + " finalTemplate=" + std::to_string(kSignonTemplateFinalRecord)
            + " map=" + (state.server_state.map_name.empty() ? std::string("c0a0") : state.server_state.map_name)
            + " name=" + (slot_state->player_name.empty() ? std::string("loopback_player") : slot_state->player_name)
            + " ruleset=" + DedicatedRulesetName(state.server_state)
            + " maxplayers=" + std::to_string(max_players)
            + " spawned=" + std::to_string(slot_state->spawn_count > 0 ? 1 : 0)
            + " signonReady=" + std::to_string(slot_state->signon_ready ? 1 : 0)
            + " bootstrapDelivered=" + std::to_string(slot_state->bootstrap_delivered ? 1 : 0)
            + " baselineReady=" + std::to_string(slot_state->baseline_ready ? 1 : 0)
            + " bootstrapSequenceCompleted="
            + std::to_string(slot_state->bootstrap_sequence_completed ? 1 : 0)
            + " signonCatalogReady=" + std::to_string(slot_state->signon_catalog_ready ? 1 : 0)
            + " bootstrapRecordsStaged="
            + std::to_string(slot_state->bootstrap_records_staged ? 1 : 0)
            + " signonTemplateReady=" + std::to_string(slot_state->signon_template_ready ? 1 : 0)
            + " templateRecordsDelivered="
            + std::to_string(slot_state->template_records_delivered ? 1 : 0)
            + " byteLength=" + std::to_string(static_cast<int>(template_bytes.size()))
            + " templateBytes=" + EncodeUpperHex(template_bytes)
            + " payload=" + DedicatedSignonTemplatePayloadName(request_template)
        : "signon_template_reject reason="
            + (reject_reason.empty() ? std::string("rejected") : reject_reason)
            + " players=" + std::to_string(players)
            + " max=" + std::to_string(max_players);
    if (!SendConnectionlessText(
            server_socket,
            template_client_address,
            template_client_address_size,
            template_response,
            &probe->detail,
            "signon template surface response"))
    {
        return false;
    }

    std::string parsed_template_response;
    if (!ReceiveConnectionlessText(
            probe_socket.Get(),
            &parsed_template_response,
            nullptr,
            nullptr,
            &probe->detail,
            "signon template probe response"))
    {
        return false;
    }

    int parsed_template = -1;
    if (ParseSignonTemplateAcceptedResponseText(
            parsed_template_response,
            probe,
            &parsed_template))
    {
        if (parsed_template == probe->parsed_final_template
            && probe->signon_template_ready > 0
            && probe->template_records_delivered > 0)
        {
            ++probe->accepted;
        }
    }
    else if (std::string parsed_reject_reason;
             ParseSignonTemplateRejectResponseText(
                 parsed_template_response,
                 &parsed_reject_reason))
    {
        ++probe->rejected;
        probe->last_reject_reason = parsed_reject_reason;
    }
    else
    {
        probe->detail = "signon template probe could not parse response: "
            + parsed_template_response;
        return false;
    }

    if (template_accepted != expect_accept)
    {
        probe->detail =
            std::string("signon template expectation mismatch expected=")
            + (expect_accept ? "accept" : "reject")
            + " response=" + parsed_template_response;
        return false;
    }

    probe->detail = "loopback signon template probe template="
        + std::to_string(requested_template)
        + " completed on 127.0.0.1:" + std::to_string(bound_port);
    return true;
}

bool PumpOneLoopbackSignonTemplateFlow(
    EngineShimState& state,
    SOCKET server_socket,
    int bound_port,
    std::string_view session_id,
    hl::game_api::DedicatedSignonTemplateProbeSummary* probe)
{
    for (int template_index = 0; template_index < 2; ++template_index)
    {
        if (!PumpOneLoopbackSignonTemplateRecordAttempt(
                state,
                server_socket,
                bound_port,
                session_id,
                template_index,
                true,
                probe))
        {
            return false;
        }
    }

    return probe != nullptr
        && probe->accepted > 0
        && probe->parsed_template_count >= 2
        && probe->parsed_final_template >= 1
        && probe->signon_template_ready > 0
        && probe->template_records_delivered > 0;
}

