bool PumpOneLoopbackSignonMessageCursorCarriedCheckpointClaimedCheckpointResumeDenialAttempt(
    EngineShimState& state,
    SOCKET server_socket,
    int bound_port,
    std::string_view claimant_session_id,
    std::string_view cursor_id,
    bool expect_accept,
    hl::game_api::DedicatedSignonMessageCursorCarriedCheckpointClaimedCheckpointResumeDenialProbeSummary*
        probe)
{
    if (probe == nullptr)
    {
        return false;
    }

    ++probe->attempts;
    probe->requested_claimant_session = std::string(claimant_session_id);
    probe->requested_cursor_id = std::string(cursor_id);

    ScopedUdpSocket probe_socket(::socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP));
    if (!probe_socket.Valid())
    {
        probe->detail =
            "signon message cursor carried checkpoint claimed checkpoint resume denial probe socket() failed WSA="
            + std::to_string(WSAGetLastError());
        return false;
    }

    const sockaddr_in server_address =
        MakeLoopbackAddress(static_cast<unsigned short>(bound_port));
    const std::string requested_claimant_session =
        claimant_session_id.empty()
        ? std::string(
            "invalid_signon_message_cursor_carried_checkpoint_claimed_checkpoint_resume_denial_claimant")
        : std::string(claimant_session_id);
    const std::string requested_cursor =
        cursor_id.empty()
        ? std::string(
            "invalid_signon_message_cursor_carried_checkpoint_claimed_checkpoint_resume_denial_cursor")
        : std::string(cursor_id);
    if (!SendConnectionlessText(
            probe_socket.Get(),
            server_address,
            sizeof(server_address),
            "signon_message_cursor_carried_checkpoint_claimed_checkpoint_resume_denial claimantSession="
                + requested_claimant_session + " cursorId=" + requested_cursor,
            &probe->detail,
            "signon message cursor carried checkpoint claimed checkpoint resume denial probe request"))
    {
        return false;
    }

    sockaddr_in claimed_checkpoint_resume_denial_client_address{};
    int claimed_checkpoint_resume_denial_client_address_size =
        sizeof(claimed_checkpoint_resume_denial_client_address);
    std::string claimed_checkpoint_resume_denial_request;
    if (!ReceiveConnectionlessText(
            server_socket,
            &claimed_checkpoint_resume_denial_request,
            &claimed_checkpoint_resume_denial_client_address,
            &claimed_checkpoint_resume_denial_client_address_size,
            &probe->detail,
            "signon message cursor carried checkpoint claimed checkpoint resume denial surface receiver"))
    {
        return false;
    }

    if (!StartsWithText(
            claimed_checkpoint_resume_denial_request,
            "signon_message_cursor_carried_checkpoint_claimed_checkpoint_resume_denial "))
    {
        probe->detail =
            "signon message cursor carried checkpoint claimed checkpoint resume denial surface received unexpected request: "
            + claimed_checkpoint_resume_denial_request;
        return false;
    }

    const std::string request_claimant_session_id =
        ExtractTokenValue(
            claimed_checkpoint_resume_denial_request,
            "claimantSession=");
    const std::string request_cursor_id =
        ExtractTokenValue(claimed_checkpoint_resume_denial_request, "cursorId=");
    std::string resolved_source_session;
    std::string resolved_issuer_target_session;
    std::string resolved_claimant_session;
    int local_current_start_message_index = -1;
    int local_current_message_count = 0;
    std::string local_next_start_message_index = "<none>";
    int local_remaining_message_count = 0;
    std::string local_resume_policy;
    std::string local_denial_reason;
    bool local_target_activated = false;
    std::string reject_reason;
    const bool claimed_checkpoint_resume_denial_accepted =
        ResolveDedicatedLoopbackSignonMessageCursorCarriedCheckpointClaimedCheckpointResumeDenial(
            state,
            request_claimant_session_id,
            request_cursor_id,
            true,
            &resolved_source_session,
            &resolved_issuer_target_session,
            &resolved_claimant_session,
            &local_current_start_message_index,
            &local_current_message_count,
            &local_next_start_message_index,
            &local_remaining_message_count,
            &local_resume_policy,
            &local_denial_reason,
            &local_target_activated,
            &reject_reason);

    RefreshDedicatedSignonMessageCursorCarriedCheckpointClaimedCheckpointResumeDenialSurfaceSnapshot(
        state);
    RefreshDedicatedSignonMessageCursorCarriedCheckpointClaimedCheckpointEofSurfaceSnapshot(
        state);
    RefreshDedicatedSignonMessageCursorCarriedCheckpointClaimedCheckpointAdvanceSurfaceSnapshot(
        state);
    RefreshDedicatedSignonMessageCursorCarriedCheckpointClaimedCheckpointBridgeSurfaceSnapshot(
        state);
    RefreshDedicatedSignonMessageCursorCarriedCheckpointClaimedResumeAllowSurfaceSnapshot(
        state);
    RefreshDedicatedSignonMessageCursorCarriedCheckpointResumeTokenClaimSurfaceSnapshot(
        state);
    RefreshDedicatedSignonMessageCursorCarriedCheckpointResumeTokenSurfaceSnapshot(state);
    RefreshDedicatedActivationSurfaceSnapshot(state);
    RefreshDedicatedConnectSurfaceSnapshot(state);
    RefreshDedicatedQuerySurfaceSnapshot(state);

    const DedicatedPlayerRuntimeSlot* claimant_slot = claimed_checkpoint_resume_denial_accepted
        ? FindDedicatedPlayerRuntimeSlotBySession(
            state.dedicated_multiplayer_foundation,
            resolved_claimant_session)
        : nullptr;
    const int players = CountDedicatedQueryPlayers(state.dedicated_multiplayer_foundation);
    const int max_players = state.server_state.maxclients;
    const std::string claimed_checkpoint_resume_denial_response =
        claimed_checkpoint_resume_denial_accepted && claimant_slot != nullptr
        ? "signon_message_cursor_carried_checkpoint_claimed_checkpoint_resume_denial sourceSession="
            + resolved_source_session
            + " issuerTargetSession=" + resolved_issuer_target_session
            + " claimantSession=" + resolved_claimant_session
            + " cursorId=" + request_cursor_id
            + " resumeAllowed=no"
            + " denialReason=" + local_denial_reason
            + " eof=yes exhausted=yes"
            + " currentStartMessageIndex="
            + std::to_string(local_current_start_message_index)
            + " currentMessageCount=" + std::to_string(local_current_message_count)
            + " nextStartMessageIndex=" + local_next_start_message_index
            + " remainingMessageCount=" + std::to_string(local_remaining_message_count)
            + " resumePolicy=" + local_resume_policy
            + " targetActivated=" + std::to_string(local_target_activated ? 1 : 0)
            + " map="
            + (state.server_state.map_name.empty()
                   ? std::string("c0a0")
                   : state.server_state.map_name)
            + " name="
            + (claimant_slot->player_name.empty()
                   ? std::string("loopback_player")
                   : claimant_slot->player_name)
            + " ruleset=" + DedicatedRulesetName(state.server_state)
            + " maxplayers=" + std::to_string(max_players)
            + " spawned=" + std::to_string(claimant_slot->spawn_count > 0 ? 1 : 0)
        : "signon_message_cursor_carried_checkpoint_claimed_checkpoint_resume_denial_reject reason="
            + (reject_reason.empty() ? std::string("rejected") : reject_reason)
            + " players=" + std::to_string(players)
            + " max=" + std::to_string(max_players);

    if (!SendConnectionlessText(
            server_socket,
            claimed_checkpoint_resume_denial_client_address,
            claimed_checkpoint_resume_denial_client_address_size,
            claimed_checkpoint_resume_denial_response,
            &probe->detail,
            "signon message cursor carried checkpoint claimed checkpoint resume denial surface response"))
    {
        return false;
    }

    std::string parsed_claimed_checkpoint_resume_denial_response;
    if (!ReceiveConnectionlessText(
            probe_socket.Get(),
            &parsed_claimed_checkpoint_resume_denial_response,
            nullptr,
            nullptr,
            &probe->detail,
            "signon message cursor carried checkpoint claimed checkpoint resume denial probe response"))
    {
        return false;
    }

    if (ParseSignonMessageCursorCarriedCheckpointClaimedCheckpointResumeDenialAcceptedResponseText(
            parsed_claimed_checkpoint_resume_denial_response,
            probe))
    {
        ++probe->accepted;
    }
    else if (std::string parsed_reject_reason;
             ParseSignonMessageCursorCarriedCheckpointClaimedCheckpointResumeDenialRejectResponseText(
                 parsed_claimed_checkpoint_resume_denial_response,
                 &parsed_reject_reason))
    {
        ++probe->rejected;
        probe->last_reject_reason = parsed_reject_reason;
    }
    else
    {
        probe->detail =
            "signon message cursor carried checkpoint claimed checkpoint resume denial probe could not parse response: "
            + parsed_claimed_checkpoint_resume_denial_response;
        return false;
    }

    PopulateSignonMessageCursorCarriedCheckpointClaimedCheckpointResumeDenialProbeLifecycle(
        state.dedicated_multiplayer_foundation,
        probe);

    if (claimed_checkpoint_resume_denial_accepted != expect_accept)
    {
        probe->detail = std::string(
                            "signon message cursor carried checkpoint claimed checkpoint resume denial expectation mismatch expected=")
            + (expect_accept ? "accept" : "reject")
            + " response=" + parsed_claimed_checkpoint_resume_denial_response;
        return false;
    }

    probe->detail =
        "loopback signon message cursor carried checkpoint claimed checkpoint resume denial probe claimantSession="
        + probe->requested_claimant_session
        + " cursorId=" + probe->requested_cursor_id
        + " completed on 127.0.0.1:" + std::to_string(bound_port);
    return true;
}

