    if (!SendConnectionlessText(
            probe_socket.Get(),
            server_address,
            sizeof(server_address),
            "signon_message_cursor_eof cursorId=" + requested_cursor_id,
            &probe->detail,
            "signon message cursor eof probe request"))
    {
        return false;
    }

    sockaddr_in eof_client_address{};
