void ResetTraceResult(TraceResult* trace, const Vector& end_position, edict_t* hit_entity)
{
    if (trace == nullptr)
    {
        return;
    }

    *trace = {};
    trace->flFraction = 1.0f;
    trace->vecEndPos = end_position;
    trace->pHit = hit_entity;
}

